const intWords = (value: number, size = 1): number[] => {
  const words: number[] = [];
  let rest = value;
  while (rest > 0 || words.length < size) {
    words.unshift(rest % 32);
    rest = Math.floor(rest / 32);
  }
  return words;
};
const field = (tag: number, data: number[]): number[] => [
  tag,
  Math.floor(data.length / 32),
  data.length % 32,
  ...data,
];

/**
 * Builds a structurally valid invoice for tests, independent of the SDK decoder.
 * The signature is zero-filled; payers in these tests never verify it.
 */
export function testBolt11(params: {
  sats?: number;
  network?: 'bc' | 'tb' | 'tbs' | 'bcrt';
  timestamp?: number;
  expirySeconds?: number;
  hashSeed?: number;
}): string {
  const words = [
    ...intWords(params.timestamp ?? Math.floor(Date.now() / 1000), 7),
    ...field(1, bech32.toWords(new Uint8Array(32).fill(params.hashSeed ?? 7))),
    ...(params.expirySeconds !== undefined
      ? field(6, intWords(params.expirySeconds))
      : []),
    ...new Array<number>(104).fill(0),
  ];
  const amount = params.sats === undefined ? '' : `${params.sats * 10}n`;
  return bech32.encode(`ln${params.network ?? 'bc'}${amount}`, words, false);
}
